            |&gt; Chart.combine
        else Chart.Point []

    let chartNoise = 
        if result.Noisepoints |&gt; Seq.length &gt; 0 then 
            result.Noisepoints
            |&gt; Seq.map (fun x -&gt; x.[0],x.[1])  
            |&gt; Seq.distinct //more efficient visualization; no difference in plot but in point numbers
            |&gt; Chart.Point
            |&gt; Chart.withTraceInfo &quot;Noise&quot;
        else Chart.Point []

    let chartname = 
